# ============================================================
# 039_SupplementaryFigure_Objective4_FiveMethodBehaviouralProfiles_v2.R
#
# OBJECTIVE 4 - SUPPLEMENTARY FIGURE
#
# Behavioural distributions generated by the five analytical
# classification frameworks.
#
# IMPORTANT
# - This script does NOT recalculate any classification.
# - It reads the definitive Objective 4 profile object generated
#   by corrected Script 035.
# - Group order is fixed as:
#       Resilient -> Intermediate -> Susceptible
# - Swaminathan-like, Two-Step, and Louvain are binary methods;
#   therefore no artificial Intermediate group is displayed for
#   those methods.
# - Colours follow the established manuscript palette:
#       Resilient    = turquoise
#       Intermediate = grey
#       Susceptible  = coral
# ============================================================


# ------------------------------------------------------------
# 0. Project directory
# ------------------------------------------------------------

project_root <- normalizePath(
  Sys.getenv(
    "LAPCOM_UCS_PROJECT_ROOT",
    unset = getwd()
  ),
  winslash = "/",
  mustWork = TRUE
)

if (!dir.exists(project_root)) {
  stop(
    "Project directory not found:\n",
    project_root
  )
}

setwd(project_root)


# ------------------------------------------------------------
# 1. Required packages
# ------------------------------------------------------------

required_packages <- c(
  "dplyr",
  "tidyr",
  "ggplot2"
)

missing_packages <- required_packages[
  !vapply(
    required_packages,
    requireNamespace,
    logical(1),
    quietly = TRUE
  )
]

if (length(missing_packages) > 0L) {
  stop(
    "Install the following packages before running this script:\n",
    paste(missing_packages, collapse = ", ")
  )
}

suppressPackageStartupMessages({
  library(dplyr)
  library(tidyr)
  library(ggplot2)
})


# ------------------------------------------------------------
# 2. Directories
# ------------------------------------------------------------

objects_dir <- file.path(
  project_root,
  "03_Results",
  "Objects"
)

figures_dir <- file.path(
  project_root,
  "03_Results",
  "Figures"
)

if (!dir.exists(figures_dir)) {
  dir.create(
    figures_dir,
    recursive = TRUE
  )
}


# ------------------------------------------------------------
# 3. Definitive upstream object
# ------------------------------------------------------------

profile_file <- file.path(
  objects_dir,
  "objective4_profile_data.rds"
)

if (!file.exists(profile_file)) {
  stop(
    "Definitive Objective 4 profile object not found:\n",
    profile_file,
    "\n\nRun corrected Script 035 first."
  )
}


# ------------------------------------------------------------
# 4. Load definitive data
# ------------------------------------------------------------

profile_data <- readRDS(
  profile_file
)


# ------------------------------------------------------------
# 5. Validate imported object
# ------------------------------------------------------------

if (!is.data.frame(profile_data)) {
  stop(
    basename(profile_file),
    " does not contain the expected data frame."
  )
}

required_columns <- c(
  "Author",
  "ID",
  "Traceability_ID",
  "Swaminathan",
  "PCA_Quantiles",
  "GMM",
  "TwoStep",
  "Louvain",
  "distance_rz",
  "crossing_rz",
  "top_entry_rz",
  "top_time_rz"
)

missing_columns <- setdiff(
  required_columns,
  names(profile_data)
)

if (length(missing_columns) > 0L) {
  stop(
    "The stored Objective 4 profile object is missing:\n",
    paste(missing_columns, collapse = ", ")
  )
}

if (nrow(profile_data) != 89L) {
  stop(
    "The stored profile object does not contain the expected ",
    "89 UCS-exposed zebrafish."
  )
}

if (anyDuplicated(profile_data$Traceability_ID) > 0L) {
  stop(
    "Duplicated Traceability_ID values were detected."
  )
}

if (
  anyNA(
    profile_data[
      required_columns
    ]
  )
) {
  stop(
    "Missing values were detected in required classification ",
    "or behavioural variables."
  )
}


# ------------------------------------------------------------
# 6. Fixed graphical order and labels
# ------------------------------------------------------------

method_order <- c(
  "Swaminathan",
  "PCA_Quantiles",
  "TwoStep",
  "Louvain",
  "GMM"
)

method_labels <- c(
  "Swaminathan" = "Swaminathan-like",
  "PCA_Quantiles" = "PCA-derived\nindex quantiles",
  "TwoStep" = "Two-Step",
  "Louvain" = "Louvain",
  "GMM" = "GMM"
)

classification_order <- c(
  "Resilient",
  "Intermediate",
  "Susceptible"
)

behaviour_order <- c(
  "distance_rz",
  "crossing_rz",
  "top_entry_rz",
  "top_time_rz"
)

behaviour_labels <- c(
  "distance_rz" = "Distance travelled",
  "crossing_rz" = "Line crossings",
  "top_entry_rz" = "Upper-zone entries",
  "top_time_rz" = "Upper-zone time"
)


# ------------------------------------------------------------
# 7. Fixed manuscript palette
# ------------------------------------------------------------

colour_turquoise <- "#63B8A6"
colour_coral <- "#F07A5A"
colour_grey_intermediate <- "grey78"

classification_colours <- c(
  "Resilient" = colour_turquoise,
  "Intermediate" = colour_grey_intermediate,
  "Susceptible" = colour_coral
)


# ------------------------------------------------------------
# 8. Prepare plotting data
# ------------------------------------------------------------

plot_data <- profile_data %>%
  dplyr::select(
    Author,
    ID,
    Traceability_ID,
    dplyr::all_of(
      method_order
    ),
    dplyr::all_of(
      behaviour_order
    )
  ) %>%

  tidyr::pivot_longer(
    cols = dplyr::all_of(
      method_order
    ),
    names_to = "Method",
    values_to = "Classification"
  ) %>%

  tidyr::pivot_longer(
    cols = dplyr::all_of(
      behaviour_order
    ),
    names_to = "Behaviour",
    values_to = "Value"
  ) %>%

  dplyr::mutate(
    Method = factor(
      Method,
      levels = method_order
    ),

    Classification = factor(
      as.character(
        Classification
      ),
      levels = classification_order
    ),

    Behaviour = factor(
      Behaviour,
      levels = behaviour_order,
      labels = unname(
        behaviour_labels[
          behaviour_order
        ]
      )
    )
  )


# ------------------------------------------------------------
# 9. Validate classification structure
# ------------------------------------------------------------

unexpected_classifications <- setdiff(
  unique(
    as.character(
      plot_data$Classification
    )
  ),
  classification_order
)

if (length(unexpected_classifications) > 0L) {
  stop(
    "Unexpected classification labels detected:\n",
    paste(
      unexpected_classifications,
      collapse = ", "
    )
  )
}

binary_methods <- c(
  "Swaminathan",
  "TwoStep",
  "Louvain"
)

binary_intermediate_counts <- plot_data %>%
  dplyr::filter(
    Method %in% binary_methods,
    Classification == "Intermediate"
  ) %>%
  dplyr::distinct(
    Method,
    Traceability_ID
  ) %>%
  dplyr::count(
    Method,
    name = "n"
  )

if (nrow(binary_intermediate_counts) > 0L) {
  stop(
    "An Intermediate classification was detected in a method ",
    "that should be binary."
  )
}


# ------------------------------------------------------------
# 10. Deterministic jitter
# ------------------------------------------------------------

jitter_seed <- 2026L

jitter_position <- ggplot2::position_jitter(
  width = 0.075,
  height = 0,
  seed = jitter_seed
)


# ------------------------------------------------------------
# 11. Build supplementary figure
# ------------------------------------------------------------

supplementary_figure <- ggplot2::ggplot(
  plot_data,
  ggplot2::aes(
    x = Classification,
    y = Value,
    group = Classification,
    fill = Classification,
    colour = Classification
  )
) +

  ggplot2::geom_hline(
    yintercept = 0,
    linetype = "dashed",
    colour = "grey50",
    linewidth = 0.45
  ) +

  ggplot2::geom_violin(
    width = 0.78,
    trim = TRUE,
    alpha = 0.20,
    linewidth = 0.75,
    show.legend = FALSE
  ) +

  ggplot2::geom_boxplot(
    width = 0.22,
    outlier.shape = NA,
    alpha = 0.72,
    colour = "black",
    linewidth = 0.60,
    show.legend = FALSE
  ) +

  ggplot2::geom_point(
    position = jitter_position,
    shape = 21,
    size = 1.55,
    stroke = 0.32,
    alpha = 0.78,
    colour = "black",
    show.legend = FALSE
  ) +

  ggplot2::scale_fill_manual(
    values = classification_colours,
    breaks = classification_order,
    drop = FALSE,
    name = NULL
  ) +

  ggplot2::scale_colour_manual(
    values = classification_colours,
    breaks = classification_order,
    drop = FALSE,
    name = NULL
  ) +

  # Free x-scales are essential here:
  # binary methods display only Resilient and Susceptible,
  # whereas PCA quantiles and GMM retain the Intermediate class.
  # Panel widths remain equal because space is not set to "free".
  ggplot2::facet_grid(
    rows = ggplot2::vars(
      Behaviour
    ),
    cols = ggplot2::vars(
      Method
    ),
    scales = "free_x",
    labeller = ggplot2::labeller(
      Method = method_labels
    )
  ) +

  ggplot2::scale_x_discrete(
    drop = TRUE
  ) +

  ggplot2::labs(
    x = NULL,
    y = "Control-referenced robust behavioural value"
  ) +

  ggplot2::theme_classic(
    base_size = 10.5,
    base_family = "Arial"
  ) +

  ggplot2::theme(
    axis.text = ggplot2::element_text(
      colour = "black"
    ),

    axis.text.x = ggplot2::element_text(
      angle = 38,
      hjust = 1,
      vjust = 1,
      size = 8.2
    ),

    axis.text.y = ggplot2::element_text(
      size = 8.8
    ),

    axis.title.y = ggplot2::element_text(
      colour = "black",
      size = 10.5,
      margin = ggplot2::margin(
        r = 7
      )
    ),

    axis.line = ggplot2::element_line(
      colour = "black",
      linewidth = 0.50
    ),

    axis.ticks = ggplot2::element_line(
      colour = "black",
      linewidth = 0.40
    ),

    strip.background = ggplot2::element_blank(),

    strip.text.x = ggplot2::element_text(
      family = "Arial",
      face = "plain",
      size = 10.3,
      colour = "black",
      margin = ggplot2::margin(
        b = 5
      )
    ),

    strip.text.y = ggplot2::element_text(
      family = "Arial",
      face = "plain",
      size = 10.0,
      colour = "black",
      angle = 270,
      margin = ggplot2::margin(
        l = 6
      )
    ),

    panel.spacing.x = grid::unit(
      0.10,
      "cm"
    ),

    panel.spacing.y = grid::unit(
      0.12,
      "cm"
    ),

    legend.position = "none",

    plot.background = ggplot2::element_rect(
      fill = "white",
      colour = NA
    ),

    panel.background = ggplot2::element_rect(
      fill = "white",
      colour = NA
    ),

    plot.margin = ggplot2::margin(
      t = 10,
      r = 12,
      b = 8,
      l = 8
    )
  )


# ------------------------------------------------------------
# 12. Display
# ------------------------------------------------------------

print(
  supplementary_figure
)


# ------------------------------------------------------------
# 13. Output paths
# ------------------------------------------------------------

figure_pdf_output <- file.path(
  figures_dir,
  "SupplementaryFigure_Objective4_FiveMethodBehaviouralProfiles_v2.pdf"
)

figure_tiff_output <- file.path(
  figures_dir,
  "SupplementaryFigure_Objective4_FiveMethodBehaviouralProfiles_v2.tiff"
)

figure_png_output <- file.path(
  figures_dir,
  "SupplementaryFigure_Objective4_FiveMethodBehaviouralProfiles_v2.png"
)

figure_object_output <- file.path(
  objects_dir,
  "supplementary_figure_objective4_five_method_behavioural_profiles_v2_plot.rds"
)

figure_data_output <- file.path(
  objects_dir,
  "supplementary_figure_objective4_five_method_behavioural_profiles_v2_data.rds"
)

session_info_output <- file.path(
  objects_dir,
  "supplementary_figure_objective4_five_method_behavioural_profiles_v2_sessionInfo.txt"
)


# ------------------------------------------------------------
# 14. Save reproducibility objects
# ------------------------------------------------------------

figure_data_object <- list(
  Figure =
    "Objective 4 supplementary five-method behavioural profiles",

  Upstream_object =
    profile_file,

  Method_order =
    method_order,

  Classification_order =
    classification_order,

  Behaviour_order =
    behaviour_order,

  Palette = list(
    Resilient =
      colour_turquoise,

    Intermediate =
      colour_grey_intermediate,

    Susceptible =
      colour_coral
  ),

  Jitter_seed =
    jitter_seed,

  Plot_data =
    plot_data
)

saveRDS(
  supplementary_figure,
  figure_object_output
)

saveRDS(
  figure_data_object,
  figure_data_output
)


# ------------------------------------------------------------
# 15. Export figure
# ------------------------------------------------------------

ggplot2::ggsave(
  filename = figure_pdf_output,
  plot = supplementary_figure,
  width = 15.0,
  height = 9.0,
  units = "in",
  device = grDevices::cairo_pdf,
  bg = "white"
)

ggplot2::ggsave(
  filename = figure_tiff_output,
  plot = supplementary_figure,
  width = 15.0,
  height = 9.0,
  units = "in",
  dpi = 600,
  compression = "lzw",
  bg = "white"
)

ggplot2::ggsave(
  filename = figure_png_output,
  plot = supplementary_figure,
  width = 15.0,
  height = 9.0,
  units = "in",
  dpi = 600,
  bg = "white"
)

capture.output(
  utils::sessionInfo(),
  file = session_info_output
)


# ------------------------------------------------------------
# 16. Confirm outputs
# ------------------------------------------------------------

expected_outputs <- c(
  figure_pdf_output,
  figure_tiff_output,
  figure_png_output,
  figure_object_output,
  figure_data_output,
  session_info_output
)

missing_outputs <- expected_outputs[
  !file.exists(expected_outputs)
]

if (length(missing_outputs) > 0L) {
  stop(
    "The following supplementary-figure outputs were not created:\n",
    paste(
      missing_outputs,
      collapse = "\n"
    )
  )
}


# ------------------------------------------------------------
# 17. Final console audit
# ------------------------------------------------------------

cat("\n============================================================\n")
cat("OBJECTIVE 4 SUPPLEMENTARY FIVE-METHOD BEHAVIOURAL PROFILES\n")
cat("============================================================\n")

cat(
  "\nNo classification was recalculated in this script.\n"
)

cat("\nGroup order:\n")
cat("Resilient -> Intermediate -> Susceptible\n")

cat("\nBinary methods without an Intermediate class:\n")
cat("Swaminathan-like\n")
cat("Two-Step\n")
cat("Louvain\n")

cat("\nFiles saved as:\n")

for (output_file_i in expected_outputs) {
  cat(
    normalizePath(
      output_file_i,
      winslash = "/",
      mustWork = FALSE
    ),
    "\n",
    sep = ""
  )
}

cat("\n============================================================\n")